SELECT TOP(512) Id AS QuestionId FROM @Posts WHERE PostTypeId=1 ORDER BY Id;
DECLARE @Count01 int=(SELECT COUNT(*) FROM @G01);
IF @Count01=0 THROW 51103,'No eligible rows for 01-pages; rerun parameter selection before starting.',1;

-- 03-users: keep each eligible tuple together.
DECLARE @G03 table(Rn int IDENTITY(1,1) PRIMARY KEY,[UserId] int NOT NULL);
