IF @Count03=0 THROW 51103,'No eligible rows for 03-users; rerun parameter selection before starting.',1;

-- 04-catalog: keep each eligible tuple together.
DECLARE @G04 table(Rn int IDENTITY(1,1) PRIMARY KEY,[PostId] int NOT NULL,[UserId] int NOT NULL,[TagName] nvarchar(150) NOT NULL);
INSERT @G04([PostId],[UserId],[TagName])
SELECT TOP(512) P.Id AS PostId,P.OwnerUserId AS UserId,T.TagName
FROM @Posts P JOIN dbo.Users U ON U.Id=P.OwnerUserId
CROSS APPLY (SELECT TOP(1) t.TagName FROM dbo.Stackish_SplitTags(P.Tags) s JOIN dbo.Tags t ON t.TagName=s.TagName ORDER BY t.Id) T
WHERE P.PostTypeId=1 AND P.OwnerUserId>0 ORDER BY P.Id;
DECLARE @Count04 int=(SELECT COUNT(*) FROM @G04);
IF @Count04=0 THROW 51103,'No eligible rows for 04-catalog; rerun parameter selection before starting.',1;

-- 05-counters: keep each eligible tuple together.
DECLARE @G05 table(Rn int IDENTITY(1,1) PRIMARY KEY,[QuestionId] int NOT NULL,[UserId] int NOT NULL);
;WITH P AS (SELECT *,ROW_NUMBER() OVER(ORDER BY Id) rn FROM @Posts WHERE PostTypeId=1),
U AS (SELECT Id,ROW_NUMBER() OVER(ORDER BY Id) rn FROM @Users)
INSERT @G05([QuestionId],[UserId])
SELECT TOP(512) P.Id AS QuestionId,U.Id AS UserId FROM P JOIN U ON U.rn=1+(P.rn-1) % NULLIF((SELECT COUNT(*) FROM @Users),0)
 ORDER BY P.Id;
