-- 06-votes: keep each eligible tuple together.
DECLARE @G06 table(Rn int IDENTITY(1,1) PRIMARY KEY,[PostId] int NOT NULL,[PostTypeId] int NOT NULL,[UserId] int NOT NULL);
;WITH P AS (SELECT *,ROW_NUMBER() OVER(ORDER BY Id) rn FROM @Posts WHERE PostTypeId IN(1,2)),
U AS (SELECT Id,ROW_NUMBER() OVER(ORDER BY Id) rn FROM @Users)
INSERT @G06([PostId],[PostTypeId],[UserId])
SELECT TOP(512) P.Id AS PostId,P.PostTypeId,U.Id AS UserId FROM P JOIN U ON U.rn=1+(P.rn-1) % NULLIF((SELECT COUNT(*) FROM @Users),0)
WHERE (P.OwnerUserId IS NULL OR P.OwnerUserId<>U.Id) AND (SELECT COUNT_BIG(*) FROM dbo.Votes v WHERE v.PostId=P.Id AND v.UserId=U.Id AND v.VoteTypeId IN(2,3))<=1 ORDER BY P.Id;
