-- 09-maintenance: keep each eligible tuple together.
DECLARE @G09 table(Rn int IDENTITY(1,1) PRIMARY KEY,[QuestionId] int NOT NULL,[AnswerId] int NOT NULL,[UserId] int NOT NULL,[RelatedQuestionId] int NOT NULL);
INSERT @G09([QuestionId],[AnswerId],[UserId],[RelatedQuestionId])
SELECT TOP(512) Q.Id AS QuestionId,P.Id AS AnswerId,Q.OwnerUserId AS UserId,R.Id AS RelatedQuestionId
FROM @Posts P JOIN dbo.Posts Q ON Q.Id=P.ParentId AND Q.PostTypeId=1
