DECLARE @G12 table(Rn int IDENTITY(1,1) PRIMARY KEY,[QuestionId] int NOT NULL,[TagName] nvarchar(150) NOT NULL,[SearchText] nvarchar(250) NOT NULL,[FromDate] datetime NOT NULL,[ToDate] datetime NOT NULL,[BadgeName] nvarchar(40) NOT NULL);
INSERT @G12([QuestionId],[TagName],[SearchText],[FromDate],[ToDate],[BadgeName])
SELECT TOP(128) P.Id AS QuestionId,T.TagName,LEFT(P.Title,12) AS SearchText,
 CONVERT(datetime,DATEADD(day,-30,P.CreationDate)) AS FromDate,
 CONVERT(datetime,DATEADD(day,1,P.CreationDate)) AS ToDate,
 B.Name AS BadgeName
FROM @Posts P
CROSS APPLY(SELECT TOP(1) t.TagName FROM dbo.Stackish_SplitTags(P.Tags) s JOIN dbo.Tags t ON t.TagName=s.TagName ORDER BY t.Id) T
