 JSON_QUERY((SELECT g09.[QuestionId],g09.[AnswerId],g09.[UserId],g09.[RelatedQuestionId] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER)) AS [09-maintenance],
 JSON_QUERY((SELECT g11.[QuestionId],g11.[UserId] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER)) AS [11-hot-counters],
